import React from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  LinearProgress,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
} from '@mui/material';
import {
  CheckCircle as CheckCircleIcon,
  RadioButtonUnchecked as UncheckedIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import type { OnboardingProgress } from '../../utils/sustainabilityUx';

export interface DashboardOnboardingChecklistProps {
  progress: OnboardingProgress;
}

export const DashboardOnboardingChecklist: React.FC<DashboardOnboardingChecklistProps> = ({ progress }) => {
  const navigate = useNavigate();

  if (progress.allComplete) {
    return null;
  }

  return (
    <Card variant="outlined" sx={{ mb: 3 }}>
      <CardContent>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 2, mb: 2 }}>
          <Box>
            <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
              Getting started
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {progress.completedCount} of {progress.totalCount} setup steps complete
            </Typography>
          </Box>
          <Typography variant="h6" sx={{ fontWeight: 800, color: 'primary.main' }}>
            {progress.percent}%
          </Typography>
        </Box>
        <LinearProgress
          variant="determinate"
          value={progress.percent}
          sx={{ height: 8, borderRadius: 1, mb: 2 }}
        />
        <List dense disablePadding>
          {progress.steps.map((step) => (
            <ListItem key={step.id} disablePadding>
              <ListItemButton onClick={() => navigate(step.path)} sx={{ borderRadius: 1 }}>
                <ListItemIcon sx={{ minWidth: 36 }}>
                  {step.complete ? (
                    <CheckCircleIcon color="success" fontSize="small" />
                  ) : (
                    <UncheckedIcon color="disabled" fontSize="small" />
                  )}
                </ListItemIcon>
                <ListItemText
                  primary={step.label}
                  secondary={step.description}
                  primaryTypographyProps={{ fontWeight: step.complete ? 500 : 600 }}
                />
              </ListItemButton>
            </ListItem>
          ))}
        </List>
        <Button size="small" sx={{ mt: 1 }} onClick={() => navigate(progress.steps.find((s) => !s.complete)?.path || '/dashboard')}>
          Continue setup
        </Button>
      </CardContent>
    </Card>
  );
};
