import React, { useState } from 'react';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import {
    Box,
    Container,
    TextField,
    Button,
    Typography,
    Alert,
    Paper,
    InputAdornment,
    IconButton,
    Link,
} from '@mui/material';
import {
    Visibility,
    VisibilityOff,
    AdminPanelSettings as AdminIcon,
} from '@mui/icons-material';
import { useForm } from 'react-hook-form';
import ApiService from '../../services/api';
import BrandLogoMark from '../BrandLogoMark';
import { persistAdminPortalSession } from '../../utils/adminPortalSession';

interface AdminLoginForm {
    email: string;
    password: string;
}

const AdminLogin: React.FC = () => {
    const navigate = useNavigate();
    const [showPassword, setShowPassword] = useState(false);
    const [loginError, setLoginError] = useState<string | null>(null);
    const [isLogging, setIsLogging] = useState(false);

    const {
        register,
        handleSubmit,
        formState: { errors },
    } = useForm<AdminLoginForm>();

    const onSubmit = async (data: AdminLoginForm) => {
        setLoginError(null);
        setIsLogging(true);

        try {
            const response = await ApiService.login(
                data.email.trim().toLowerCase(),
                data.password,
            );

            if (!response?.success) {
                throw new Error(response?.message || 'Login failed');
            }

            const user = response?.data?.user;
            const token = response?.data?.token;

            if (user?.role !== 'admin' && user?.role !== 'view') {
                localStorage.removeItem('token');
                throw new Error(
                    'This account is not authorized for the reviewer portal. Use MSME sign-in for business accounts.',
                );
            }

            if (!token || !user) {
                throw new Error('Login failed. No session returned.');
            }

            persistAdminPortalSession(user, token);
            navigate('/admin/dashboard');
        } catch (error) {
            setLoginError(
                error instanceof Error
                    ? error.message
                    : 'Login failed. Please check your credentials.'
            );
        } finally {
            setIsLogging(false);
        }
    };

    return (
        <Box
            sx={{
                minHeight: '100vh',
                background: '#e4f3e5',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                py: 4,
            }}
        >
            <Container maxWidth="sm">
                <Paper
                    elevation={24}
                    sx={{
                        p: 4,
                        borderRadius: 3,
                        backdropFilter: 'blur(10px)',
                        background: 'rgba(255, 255, 255, 0.95)',
                    }}
                >
                    <Box sx={{ textAlign: 'center', mb: 4 }}>
                        <BrandLogoMark width={180} sx={{ mb: 2 }} />
                        <AdminIcon
                            sx={{
                                fontSize: 40,
                                color: 'primary.main',
                                mb: 1,
                            }}
                        />
                        <Typography
                            variant="h4"
                            component="h1"
                            gutterBottom
                            sx={{ fontWeight: 700, color: 'primary.main' }}
                        >
                            Admin &amp; reviewer portal
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                            For platform administrators and credentialed reviewers (auditors, bank
                            partners, verification agencies).
                        </Typography>
                    </Box>

                    {loginError && (
                        <Alert severity="error" sx={{ mb: 3 }}>
                            {loginError}
                        </Alert>
                    )}

                    <form onSubmit={handleSubmit(onSubmit)}>
                        <TextField
                            fullWidth
                            label="Work email"
                            type="email"
                            margin="normal"
                            {...register('email', {
                                required: 'Email is required',
                                pattern: {
                                    value: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i,
                                    message: 'Invalid email address',
                                },
                            })}
                            error={Boolean(errors.email)}
                            helperText={errors.email?.message}
                            autoFocus
                        />

                        <TextField
                            fullWidth
                            label="Password"
                            type={showPassword ? 'text' : 'password'}
                            margin="normal"
                            {...register('password', {
                                required: 'Password is required',
                                minLength: {
                                    value: 6,
                                    message: 'Password must be at least 6 characters',
                                },
                            })}
                            error={Boolean(errors.password)}
                            helperText={errors.password?.message}
                            InputProps={{
                                endAdornment: (
                                    <InputAdornment position="end">
                                        <IconButton
                                            onClick={() => setShowPassword(!showPassword)}
                                            edge="end"
                                            aria-label={showPassword ? 'Hide password' : 'Show password'}
                                        >
                                            {showPassword ? <VisibilityOff /> : <Visibility />}
                                        </IconButton>
                                    </InputAdornment>
                                ),
                            }}
                        />

                        <Button
                            type="submit"
                            fullWidth
                            variant="contained"
                            size="large"
                            disabled={isLogging}
                            sx={{
                                mt: 3,
                                py: 1.5,
                                fontWeight: 600,
                                fontSize: '1.1rem',
                            }}
                        >
                            {isLogging ? 'Signing in…' : 'Sign in to portal'}
                        </Button>
                    </form>

                    <Box sx={{ mt: 3, textAlign: 'center' }}>
                        <Typography variant="body2" color="text.secondary">
                            MSME or enterprise account?{' '}
                            <Link component={RouterLink} to="/register?type=msme">
                                Sign in to the carbon workspace
                            </Link>
                        </Typography>
                        <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                            Authorized personnel only. All access is logged.
                        </Typography>
                    </Box>
                </Paper>
            </Container>
        </Box>
    );
};

export default AdminLogin;
