/** Webpack may emit a string URL or a `{ default: string }` module for static assets. */
export function normalizeAssetUrl(
  asset: string | { default?: string } | null | undefined
): string {
  if (!asset) {
    return '';
  }
  if (typeof asset === 'string') {
    return asset;
  }
  if (typeof asset === 'object' && typeof asset.default === 'string') {
    return asset.default;
  }
  return '';
}
