import React from 'react';
import { Box, Typography, type TypographyProps } from '@mui/material';
import { BRAND_NAME_LINE_2, BRAND_TAGLINE } from '../constants/brand';

export type BrandProductNameSize = 'compact' | 'default' | 'large';

export interface BrandProductNameProps {
  size?: BrandProductNameSize;
  align?: TypographyProps['align'];
  /** When true, shows the Measure · Report · Reduce tagline below the product name. */
  showTagline?: boolean;
}

const SIZE_STYLES: Record<
  BrandProductNameSize,
  { line1: TypographyProps['variant']; line2: TypographyProps['variant']; line1Size?: string; line2Size?: string }
> = {
  compact: {
    line1: 'subtitle2',
    line2: 'subtitle1',
    line1Size: '0.8rem',
    line2Size: '0.95rem',
  },
  default: {
    line1: 'h6',
    line2: 'h5',
  },
  large: {
    line1: 'h5',
    line2: 'h4',
    line1Size: '1.35rem',
    line2Size: '1.65rem',
  },
};

/**
 * Two-line product name aligned with the Sustainow launch logo lockup.
 */
const SustainowWordmark: React.FC<{ fontSize?: string }> = ({ fontSize }) => (
  <Box
    component="span"
    sx={{
      fontSize,
      textTransform: 'lowercase',
    }}
  >
    sust
    <Box component="span" sx={{ color: 'primary.dark' }}>
      ai
    </Box>
    now
  </Box>
);

const BrandProductName: React.FC<BrandProductNameProps> = ({
  size = 'default',
  align = 'left',
  showTagline = false,
}) => {
  const styles = SIZE_STYLES[size];

  return (
    <Box sx={{ textAlign: align, minWidth: 0 }}>
      <Typography
        variant={styles.line1}
        component="div"
        sx={{
          fontWeight: 700,
          lineHeight: 1.1,
          letterSpacing: '-0.02em',
          color: 'primary.main',
          fontSize: styles.line1Size,
        }}
      >
        <SustainowWordmark fontSize={styles.line1Size} />
      </Typography>
      <Typography
        variant={styles.line2}
        component="div"
        sx={{
          fontWeight: 700,
          lineHeight: 1.15,
          letterSpacing: '-0.02em',
          color: 'primary.dark',
          fontSize: styles.line2Size,
        }}
      >
        {BRAND_NAME_LINE_2}
      </Typography>
      {showTagline && (
        <Typography
          variant="caption"
          component="div"
          sx={{
            color: 'text.secondary',
            fontWeight: 500,
            lineHeight: 1.2,
            mt: 0.25,
            display: { xs: 'none', sm: 'block' },
          }}
        >
          {BRAND_TAGLINE}
        </Typography>
      )}
    </Box>
  );
};

export default BrandProductName;
