export type BillingInterval = 'monthly' | 'yearly';

export type PlanTier = 'free' | 'starter' | 'core' | 'growth' | 'scale';

export interface PlanLimits {
  sites: number | null;
  users: number;
  documentsPerMonth: number;
  complianceHub: boolean;
  brsrExports: boolean;
  greenFinance: boolean;
  carbonCredits: boolean;
}

export interface PublicFixedPlan {
  planId: string;
  name: string;
  description: string;
  amountInr: number;
  amountInrInclGst?: number;
  interval: BillingInterval;
  tier?: PlanTier;
  requiresPayment?: boolean;
  limits?: PlanLimits;
  isPopular?: boolean;
}

export interface PricingGuidance {
  defaultPricingModel: 'fixed_plan' | 'usage_based';
  recommendedPopularPlanId: string;
  usageRole: string;
  usageGuidance: string;
}

export interface EnterprisePricingPackage {
  id: string;
  name: string;
  description: string;
  annualRangeInr: { min: number; max: number | null };
  unitPricing?: { label: string; perUnitInr: number };
  features?: string[];
}

export interface EnterprisePricingFramework {
  currency: string;
  billingModel: string;
  summary: string;
  packages: EnterprisePricingPackage[];
  addOns: Array<{
    id: string;
    name: string;
    oneTimeRangeInr?: { min: number; max: number };
    oneTimeInr?: number;
    creditableToAnnual?: boolean;
  }>;
  contactEmail: string;
}

export interface ChannelPricingModel {
  id: string;
  name: string;
  description: string;
  annualRangeInr?: { min: number; max: number };
  perUnitInr?: number;
  msmeMonthlyInr?: number;
}

export interface ChannelPricing {
  currency: string;
  summary: string;
  models: ChannelPricingModel[];
  contactEmail: string;
}

export interface PublicPricingData {
  currency: string;
  pricesExclusiveOfGst: boolean;
  gstRate?: number;
  moduleEnabled: boolean;
  informationalOnly: boolean;
  provider: string;
  paymentMethods: { upi: boolean; netBanking: boolean; cards: boolean };
  guidance?: PricingGuidance;
  fixedPlans: PublicFixedPlan[];
  usagePricing: {
    currency: string;
    baseAmountInr: number;
    typicalRangeInr: { min: number; max: number };
    starterFloorInr?: number;
    overagePerDocumentInr?: number;
    summary: string;
    factors: Array<{ key: string; label: string; description: string }>;
  };
  enterprisePricing?: EnterprisePricingFramework;
  channelPricing?: ChannelPricing;
  billingNote: string;
}

