export const formatInr = (value: number, currency = 'INR'): string =>
  new Intl.NumberFormat('en-IN', { style: 'currency', currency, maximumFractionDigits: 0 }).format(
    value
  );

export const formatInrRange = (
  min: number,
  max: number | null,
  currency = 'INR'
): string => {
  if (max == null) {
    return `${formatInr(min, currency)}+`;
  }
  return `${formatInr(min, currency)} – ${formatInr(max, currency)}`;
};

export const TIER_DISPLAY_ORDER: PlanTier[] = ['free', 'starter', 'core', 'growth', 'scale'];

export const TIER_DISPLAY_NAMES: Record<PlanTier, string> = {
  free: 'Free',
  starter: 'Starter',
  core: 'Core',
  growth: 'Growth',
  scale: 'Scale',
};

export const planTierKey = (plan: PublicFixedPlan): PlanTier =>
  plan.tier ?? resolvePlanTierKey(plan.planId);

/** One card per tier for the selected billing interval (Scale is annual-only). */
export const pickPlanForTier = (
  plans: PublicFixedPlan[],
  tier: PlanTier,
  interval: BillingInterval
): PublicFixedPlan | null => {
  const forTier = plans.filter((p) => planTierKey(p) === tier);
  if (forTier.length === 0) {
    return null;
  }
  if (tier === 'free') {
    return forTier.find((p) => planTierKey(p) === 'free') ?? forTier[0];
  }
  if (tier === 'scale') {
    return forTier.find((p) => p.interval === 'yearly') ?? forTier[0];
  }
  return forTier.find((p) => p.interval === interval) ?? null;
};

export const plansForBillingInterval = (
  plans: PublicFixedPlan[],
  interval: BillingInterval
): PublicFixedPlan[] =>
  TIER_DISPLAY_ORDER.map((tier) => pickPlanForTier(plans, tier, interval)).filter(
    (plan): plan is PublicFixedPlan => plan != null
  );

/** Approximate savings vs paying monthly for 12 months (null if not comparable). */
export const annualSavingsPercent = (
  plans: PublicFixedPlan[],
  tier: PlanTier
): number | null => {
  if (tier === 'free' || tier === 'scale') {
    return null;
  }
  const monthly = pickPlanForTier(plans, tier, 'monthly');
  const yearly = pickPlanForTier(plans, tier, 'yearly');
  if (!monthly?.amountInr || !yearly?.amountInr) {
    return null;
  }
  const fullYearMonthly = monthly.amountInr * 12;
  if (fullYearMonthly <= yearly.amountInr) {
    return null;
  }
  return Math.round(((fullYearMonthly - yearly.amountInr) / fullYearMonthly) * 100);
};

export const resolvePlanTierKey = (planId: string): PlanTier => {
  if (planId.includes('free')) {
    return 'free';
  }
  if (planId.includes('scale') || planId.includes('enterprise')) {
    return 'scale';
  }
  if (planId.includes('growth')) {
    return 'growth';
  }
  if (planId.includes('core')) {
    return 'core';
  }
  return 'starter';
};

export const lowestMonthlyPlanInr = (plans: PublicFixedPlan[]): number => {
  const monthly = plans
    .filter((p) => p.interval === 'monthly' && (p.requiresPayment !== false) && p.amountInr > 0)
    .map((p) => p.amountInr);
  if (monthly.length === 0) {
    return 1999;
  }
  return Math.min(...monthly);
};

export const formatPlanLimitsLine = (limits?: PlanLimits): string | null => {
  if (!limits) {
    return null;
  }
  const sites = limits.sites == null ? 'Unlimited sites' : `${limits.sites} site${limits.sites === 1 ? '' : 's'}`;
  return `${sites} · ${limits.users} users · ${limits.documentsPerMonth} docs/mo`;
};
